 static void spawn(String type,double x,double z,double angle)throws Exception{var p=v().origin.nativePoint(new Vec3(x,64,z));v().session.send("TEST_SPAWN "+type+" "+p.x+" "+p.y+" "+p.z+" 2 "+angle);}
 static int find(String type){return v().state.objects().stream().filter(a->a.template().equals(type)).mapToInt(NativeSession.Actor::id).max().orElse(0);}
 static void damage(int id)throws Exception{v().session.send("TEST_DAMAGE "+id+" 99999");}
